 for match in matches:
  start=match.start();brace=source.index('{',start)
  if ';'in source[start:brace]:continue
  depth=1;end=brace+1
  while depth:
   depth+=(source[end]=='{')-(source[end]=='}');end+=1
  return source[start:end]
